// Work out the reporting window: the last 7 days, ending now.
const cfg = $input.first().json;
const until = new Date();
const since = new Date(until.getTime() - 7 * 24 * 60 * 60 * 1000);
const iso = d => d.toISOString();
return [{
  json: {
    ...cfg,
    since: iso(since),
    until: iso(until),
    weekLabel: `${iso(since).slice(0, 10)} to ${iso(until).slice(0, 10)}`,
  },
}];

// Turn the three GitHub responses into one compact prompt.
const cfg = $('Config').first().json;
const win = $('Compute window').first().json;
const since = new Date(win.since);
const inWindow = d => d && new Date(d) >= since;

const commits = $('Get commits').all().map(i => i.json).filter(c => c && c.sha);
const issues = $('Get closed issues').all().map(i => i.json).filter(i => i && i.number && !i.pull_request);
const pulls = $('Get merged PRs').all().map(i => i.json).filter(p => p && p.number);

const commitLines = commits
  .filter(c => inWindow(c.commit && c.commit.author && c.commit.author.date))
  .map(c => `- ${String(c.commit.message).split('\n')[0]} (${(c.commit.author && c.commit.author.name) || 'unknown'})`);

const issueLines = issues
  .filter(i => inWindow(i.closed_at))
  .map(i => `- #${i.number} ${i.title}`);

const prLines = pulls
  .filter(p => p.merged_at && inWindow(p.merged_at))
  .map(p => `- #${p.number} ${p.title} (by ${(p.user && p.user.login) || 'unknown'})`);

const context = [
  `Repository: ${cfg.repoOwner}/${cfg.repoName}`,
  `Week: ${win.weekLabel}`,
  '',
  `Commits (${commitLines.length}):`,
  commitLines.join('\n') || '- (none)',
  '',
  `Closed issues (${issueLines.length}):`,
  issueLines.join('\n') || '- (none)',
  '',
  `Merged pull requests (${prLines.length}):`,
  prLines.join('\n') || '- (none)',
].join('\n');

const langInstruction = String(cfg.language).toUpperCase() === 'FR'
  ? 'Write the summary in French.'
  : 'Write the summary in English.';

const prompt = [
  'You are writing a weekly development summary for a software team.',
  langInstruction,
  'Write 3 to 5 short paragraphs: what shipped, what was fixed, and what the',
  'theme of the week was. Be concrete, name the actual work, and do not invent',
  'anything that is not in the data below. No bullet lists, no headings, no',
  'preamble like "Here is the summary".',
  '',
  context,
].join('\n');

return [{
  json: {
    ...cfg,
    context,
    prompt,
    counts: {
      commits: commitLines.length,
      closedIssues: issueLines.length,
      mergedPRs: prLines.length,
    },
  },
}];

// Pull the text out of the Claude response and shape the webhook payload.
const res = $input.first().json;
const cfg = $('Config').first().json;
const counts = $('Build context').first().json.counts;

const summary = (res.content || [])
  .map(block => block.text || '')
  .join('')
  .trim();

if (!summary) {
  throw new Error('Claude returned no text: ' + JSON.stringify(res).slice(0, 400));
}

const header = `Weekly dev summary - ${cfg.repoOwner}/${cfg.repoName} (${$('Compute window').first().json.weekLabel})`;
const stats = `${counts.commits} commits | ${counts.closedIssues} issues closed | ${counts.mergedPRs} PRs merged`;
const message = `${header}\n${stats}\n\n${summary}`;

// Discord uses `content`, Slack uses `text`.
const payload = String(cfg.deliveryTarget).toLowerCase() === 'slack'
  ? { text: message }
  : { content: message };

return [{ json: { ...cfg, summary, message, payload, counts } }];
